R=Path(__file__).resolve().parents[1];consumer=Path(sys.argv[1]);case=sys.argv[2];lane=sys.argv[3];out=R/'prepared'/lane/case;sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest();read=lambda p:json.loads(Path(p).read_text());m_path=consumer/'prepared'/case/'native/MF_INPUTS.json';m=read(m_path)
