for src,name in [(ref,'reference49_8fps.mp4'),(v,'native_full158.mp4'),(gate,'NATIVE_RUNTIME_GATE.json'),(prov_path,'SOURCE_PROVENANCE.json'),(m_path,'CONSUMER_MF_INPUTS.json')]:shutil.copy2(src,out/name)
helper=R.parent/'h3-flexiact-character-repair-mf-r98-20261019/runtime/release/release49.py';assert sha(helper)=='5bd956e4225d23e97429c4a09d8302477b6d392b176392e13ce0faf8b41fef3f';spec=importlib.util.spec_from_file_location('unchanged_release49',helper);module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);mapping=module.run(out/'native_full158.mp4',out/'native49_8fps.mp4')
info=json.loads(subprocess.check_output(['/opt/homebrew/bin/ffprobe','-v','error','-select_streams','v:0','-show_entries','stream=width,height,avg_frame_rate:frame=best_effort_timestamp_time','-of','json',str(out/'reference49_8fps.mp4')],text=True));assert len(info['frames'])==49 and info['streams'][0]['avg_frame_rate']=='8/1' and all(abs(float(x['best_effort_timestamp_time'])-i/8)<1e-6 for i,x in enumerate(info['frames']))
