(out/'CPU_READY.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'path':str(out/'CPU_READY.json'),'sha256':sha(out/'CPU_READY.json'),'GPU_started':False}))
